    if($path==='/admin/products'&&$method==='POST'){
        requireCsrf();requireUser('admin');$name=trim((string)($_POST['name']??''));$category=(string)($_POST['category']??'');$price=(int)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$sku=trim((string)($_POST['sku']??''));if(mb_strlen($name)<2||!in_array($category,['women','men','unisex','niche'],true)||$price<1||$sku==='')fail('اطلاعات محصول کامل نیست.',422);$image=saveProductImage($_FILES['image']??null);$slug='product-'.bin2hex(random_bytes(5));$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO products(name,slug,description,image_path,category,active)VALUES(?,?,?,?,?,?)')->execute([$name,$slug,trim((string)($_POST['description']??'')),$image,$category,(int)(($_POST['active']??'0')==='1')]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO product_variants(product_id,sku,color,size,price,stock)VALUES(?,?,"default",NULL,?,?)')->execute([$id,$sku,$price,$stock]);$pdo->commit();audit('product_created','product',$id);respond(['ok'=>true,'id'=>$id],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
