        requireCsrf();requireUser('admin');$id=(int)$m[1];$name=trim((string)($_POST['name']??''));$category=(string)($_POST['category']??'');$price=(int)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$sku=trim((string)($_POST['sku']??''));if(mb_strlen($name)<2||!in_array($category,['women','men','unisex','niche'],true)||$price<1||$sku==='')fail('اطلاعات محصول کامل نیست.',422);$image=saveProductImage($_FILES['image']??null);$pdo=db();$pdo->beginTransaction();try{$sql='UPDATE products SET name=?,description=?,category=?,active=?'.($image?',image_path=?':'').' WHERE id=?';$args=[$name,trim((string)($_POST['description']??'')),$category,(int)(($_POST['active']??'0')==='1')];if($image)$args[]=$image;$args[]=$id;$pdo->prepare($sql)->execute($args);$stmt=$pdo->prepare('SELECT id FROM product_variants WHERE product_id=? ORDER BY id LIMIT 1');$stmt->execute([$id]);$variant=$stmt->fetchColumn();if($variant)$pdo->prepare('UPDATE product_variants SET sku=?,price=?,stock=? WHERE id=?')->execute([$sku,$price,$stock,$variant]);else $pdo->prepare('INSERT INTO product_variants(product_id,sku,color,price,stock)VALUES(?, ?, "default", ?, ?)')->execute([$id,$sku,$price,$stock]);$pdo->commit();audit('product_updated','product',$id);respond(['ok'=>true]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
